// Editorial explanations: each lesson has its own causal chain and transfer check.
// Check answers are learning material; reading them never changes quiz accuracy.
import {addDepth as D} from './depth-data.js';
import './depth-systems.js';
import './depth-algorithms.js';
import './depth-hardware.js';
import './depth-linux-project.js';
export {lessonDepth} from './depth-data.js';

D('c-start-variable','变量名、类型和值，为什么要分开看？',[
 'int count = 3; 可以拆成三件事：int 约定保存什么类型的数据，count 给这份数据起名字，3 是创建时放进去的值。分号结束这条声明。',
 'count = count + 1; 先读取右边的旧值 3，计算得到 4，再把 4 写回左边的对象。这不是数学等式，而是一次有先后顺序的存储操作。',
 '名字用于在代码里找到对象，类型决定允许的操作，值则会随执行变化。先为变量画“名字 / 类型 / 当前值”三列，后面读指针和结构体时仍沿用这三列。'
],'未初始化的局部自动 int 没有可供你猜测的默认业务值。先初始化，再读取；全局或静态存储对象的零初始化是另一条规则。','变量是带类型的存储对象。声明创建对象，初始化给第一个值，后续赋值改变它保存的内容。读代码时，我会区分变量名、类型和当前值，并按语句顺序更新。','int n=4; n=n+2; int m=n; n=1; 最后 m 为什么没有跟着变？','m 在初始化时复制了当时的整数 6。它是另一个对象，后来给 n 写入 1 不会自动改 m。两个变量保存相同数值，不代表共享同一块对象。','把每条语句拆成“读取哪些旧值、算出什么、写给哪个对象”，再更新表格。');
D('c-start-bytes','占 4 字节与数值为 4，为什么不是一回事？',[
 'bit 是一个二进制位，可表示 0 或 1；byte 是按字节寻址时的存储单位。常见 STM32 环境一字节有 8 位，4 字节就是 32 位存储空间。',
 '存储空间相当于容器容量，数值相当于容器里的内容。一个 4 字节 int 可以保存 0、4、100 等数值，不会因为数值是 1 就只占 1 字节。',
 '位数影响可表示的组合数：8 位有 2^8 种位模式。但这些模式怎样解释成正负数、字符或其他数据，还取决于类型与表示约定。'
],'C 保证 sizeof(char)=1 个 C 字节，不能脱离 CHAR_BIT 把所有 C 实现的字节都断言为 8 位。本文 STM32 示例按 CHAR_BIT=8。','bit 是二进制位，byte 是存储单位。对象占用的字节数由类型和布局决定，与当前数值不是一回事。常见 MCU 字节是 8 位，但可移植代码应核对 CHAR_BIT。','假设 int 为 4 字节，int x=1; x=100; 前后空间大小变了吗？','没有。对象仍是 int，普通 int 的类型大小不随数值变化；只更新其中保存的位模式。','先标出题目给定的单位，把“位、字节、元素个数、数值”各自列清。');
D('c-start-expression','为什么先算右边，再理解等号左边？',[
 '表达式会产生一个结果。例如 x+2 读取 x 的当前值再加 2；x==2 比较是否相等，在 C 中产生 0 或 1；它们都不同于把 2 写入 x 的 x=2。',
 '括号先规定表达式的分组，运算符优先级规定怎样结合；执行顺序是另一层规则。初学先将复杂表达式拆成独立语句，不用凭视觉从左往右猜。',
 'if (x==2) 先得到条件真假，再决定是否执行分支。&& 和 || 具有短路规则，前半部分已能决定真假时，后半部分不会求值。'
],'优先级不等于操作数求值顺序。包含多次修改同一变量的复杂表达式，先检查语言的顺序规则，不能靠实测一次认定固定结果。','赋值、比较和算术分别做不同的事。我会先确认运算符含义、括号与类型，再判断读写顺序。对逻辑与和逻辑或，还要考虑短路，不把所有子表达式都当作必执行。','int x=0; if (x!=0 && 10/x>1) 会执行除法吗？','不会。左边 x!=0 为假，逻辑与已经确定为假，右边被短路。这里是 && 的求值规则在避免除零，不是除零本身合法。','先画表达式分组，再标出会被短路跳过的部分；将副作用单独写一行。');
D('c-sizeof','sizeof 究竟在询问什么，而不是执行什么？',[
 'sizeof 是运算符，回答某个类型或对象需要多少 C 字节。sizeof(int) 对类型提问；sizeof x 对 x 的类型提问，不是读取 x 保存的整数。',
 '普通非变长类型的操作数不求值。因此 sizeof(x++) 不会按你看到的 ++ 去增加 x；它只根据表达式的类型计算大小。变长数组相关规则需要另外学习。',
 '数组与指针要分开：完整数组的 sizeof 是各元素空间的总和；指针对象只保存一个地址，sizeof 指针无法得知目标数组的长度。结果用 size_t 表示，printf 通常配 %zu。'
],'本文基础例子不使用 VLA。不要把“sizeof 通常不求值”省略成所有情况下绝对不求值；也不要把 sizeof 当作 strlen。','sizeof 返回存储大小，类型是 size_t，单位是 C 字节。完整数组得到总大小，指针得到自身大小。普通非变长类型的操作数不求值，具体数值还需要平台类型大小。','int x=3; size_t n=sizeof(x++); 如果 int 为 4 字节，x 与 n 各是多少？','x 仍为 3，n 为 4。sizeof 根据这个非变长表达式的类型计算大小，没有执行 x++ 的修改。','先识别操作数的类型，再检查是否为完整数组或指针，并核对平台大小。');
D('c-address','为什么取得地址不会取得对象的整数内容？',[
 '把 int x=10; 想成一个有位置的格子。x 读取格子里的 10，&x 取得格子的位置；位置与格子里的内容分别回答“在哪里”和“是什么”。',
 '执行 x=20; 更新的是同一对象里的内容。只要这个对象仍在同一次生命周期中，普通赋值不会把它搬到一个新位置，所以地址和内容可以独立变化。',
 '地址也具有类型：&x 是 int*，告诉后续代码这是一个 int 对象的位置。地址的打印或数值大小并不能单独证明它可安全访问。'
],'地址图中的十六进制位置只是示意。真实地址由运行环境决定；打印对象指针常写 printf("%p", (void *)&x)。','x 读取值，&x 取得地址。值改变不意味着地址改变。地址带有所指类型，后续沿地址访问之前，还需要确认目标对象的生命周期和访问范围。','x 从 10 改成 20 后，为什么 &x 不必跟着变？','修改内容和移动对象是两件事。普通赋值把新数值写入同一个仍存活的对象，取到的仍是该对象的位置。','分别画“对象所在位置”和“对象内保存内容”，不要将两列合并。');
D('c-pointer-declare','指针 p 自己为什么也需要一块存储？',[
 'int *p=&x; 创建了指针对象 p。右边 &x 算出 x 的地址，这个地址被存入 p；因此 x 与 p 是两份对象，各有自己的位置和值。',
 '声明里的 * 属于类型声明，说明 p 指向 int；之后表达式里的 *p 才是沿地址访问目标。相同符号出现在不同语法位置，意义需要按上下文区分。',
 'p 的值是目标地址，&p 是指针对象自己的地址，*p 是目标的内容。先把这三者分开，才可能理解二级指针和函数的输出参数。'
],'int *p; 仅声明一个未初始化的局部指针，并没有自动分配 int 目标。使用 *p 前，必须建立合法目标。','指针是保存地址的对象。int *p=&x 中 p 保存 x 的地址，&p 是 p 自己的地址，*p 访问 x。声明不会自动创建一个额外的整数目标，解引用必须有有效对象。','int x=8; int *p=&x; 这里创建了几个变量？p 里面是 8 吗？','两个变量：整数 x 和指针 p。x 保存 8，p 保存 x 的地址；只有 *p 才读取目标的 8。','将声明中的类型和变量名先拆开，再分别列出 p、&p、*p 的对象层次。');
D('c-dereference','为什么 *p 有时读值，有时改值？',[
 '解引用可以理解成“沿地址找到目标”。int y=*p; 先找到 p 所指的整数，再读取它的值并复制给 y。',
 '*p=9; 的左边指定的是目标对象，所以把 9 写进目标；它没有给指针 p 重新赋一个地址。读还是写，要继续看表达式所在的位置。',
 '两种用法都要求目标有效。空指针、目标已销毁、超出对象范围或违反访问类型规则，都会让“沿地址访问”失去合法前提。'
],'不是看到 * 就一定修改目标。读取 *p 不会自动写回；p 本身重新赋值也不会沿旧地址修改对象。','*p 指定 p 当前所指对象。用于读取时取得目标值，作为赋值左边时写目标。指针必须有效，且目标仍存活、类型和访问范围合适。','int x=2; int *p=&x; int y=*p; *p=6; 最后 y 为什么还是 2？','初始化 y 时复制了当时的整数 2。后来通过 p 改的是 x，y 没有成为 x 的别名。','先沿 p 找目标，再判断目标表达式是被读取还是处在赋值左侧。');
D('c-pointer-change','为什么先看等号左边，就能分清改谁？',[
 'p=&b; 的左边是指针对象 p。它保存的内容从 a 的地址变为 b 的地址，a 和 b 的整数内容都没有因此被写入。',
 '*p=9; 的左边是当前目标。执行前必须先追踪 p 的地址；如果它已指向 b，这次写入的是 b，而不是最初的 a。',
 '语句顺序决定数据流。先写 *p 再改 p，与先改 p 再写 *p，可能修改两个不同对象。每执行一行只更新被写入的格子，其余格子保持原值。'
],'不要只记“*p 会改 a”。它修改的是当时的目标，目标会随 p 的赋值改变。','p= 修改指针保存的地址，*p= 修改当前目标。判断时先看等号左边，再按执行顺序追踪目标；改变指向不会自动复制两个整数，也不会改掉旧目标。','int a=2,b=5; int *p=&a; *p=7; p=&b; 最后 a、b、*p 是多少？','a 为 7，b 为 5，*p 为 5。写目标发生在 p 指向 a 时；随后换到 b，只改变 p 的地址。','给每次赋值标注“写指针”或“写目标”，然后按顺序移动箭头。');
D('c-array-start','为什么数组下标 1 是第二个元素？',[
 '数组下标表示相对首元素的偏移，而不是日常的“第几个”。偏移 0 是起点，偏移 1 才是下一个元素，所以 n 个元素的有效下标是 0 到 n-1。',
 '连续存放意味着同类型相邻元素间隔 sizeof 元素。a[i] 可以按“从首元素前进 i 个元素，再访问”理解，后面学习指针算术会用到这条关系。',
 '数组对象的总空间是元素数乘元素大小，但合法访问还需要下标在范围内。尾后位置可以作为某些边界计算的终点，不是一个额外可读元素。'
],'C 不会对普通数组下标自动做运行时检查。a[n] 越界时，“刚好读到某个值”不能证明代码正确。','数组连续保存同类型元素，下标从零开始。访问第 i 项相当于从首元素偏移 i 个元素；计算总大小与检查合法下标是两件需要分别做的事。','int a[3]={4,5,6}; 要读取最后一个元素，为什么写 a[2]？','数组只有下标 0、1、2 三个有效元素，数量 3 是尾后位置，不是最后一个有效下标。','先写出长度与有效下标区间，再逐个检查表达式是否仍在区间内。');
D('c-function-start','复制一个地址，为什么仍然能修改调用者？',[
 'C 参数按值传递。传整数时，形参复制整数；传指针时，形参复制的是地址。复制行为相同，只是复制的值类型不同。',
 '两个指针对象可以保存同一目标的地址。函数里对 *p 赋值，会沿复制的地址访问调用者的对象，所以目标变化可以被调用者看见。',
 '给形参 p 重新赋地址，只改变函数内部那个指针副本。若要修改调用者的指针变量本身，需要传入该指针变量的地址，即再增加一层间接访问。'
],'“传地址”不等于 C 增加了引用传递。返回局部自动对象地址也不能解决输出参数问题，因为返回后对象已经结束生命周期。','C 始终按值传参。指针形参得到地址副本，通过副本解引用可修改共同目标；给指针形参本身赋值，不能直接修改调用者的指针变量。','void f(int *p){ p=NULL; } 调用 f(q) 后，q 必然变 NULL 吗？','不会。f 修改的是形参指针副本。想改 q 本身，应设计 int** 输出参数并写 *pp，且处理空参数与所有权。','把调用者对象、形参副本与共同目标分别画出来，明确每条写入落在哪一层。');
D('c-struct-start','为什么一份结构体可以同时保存不同类型的成员？',[
 '数组用下标组织同类型数据，结构体用成员名组织一条记录。struct Sensor { int id; float value; }; 定义记录的布局，struct Sensor s; 才创建具体记录对象。',
 's.id 用点号访问这份记录中的成员。指向记录的指针 p 用 p->id，等价于 (*p).id：先找到记录，再访问它的字段。',
 '普通结构体赋值会复制成员值；如果成员中保存了指针，复制的仍只是地址，目标缓冲区不会自动深拷贝。记录布局还可能包含对齐填充。'
],'结构体定义不是把成员变量自动创建成全局变量。把结构体原始内存直接当通信报文，还会受到填充和大小端影响。','结构体把相关字段组织为一种记录类型，变量才是具体记录。点号访问对象成员，箭头访问指针目标成员；指针成员的复制需要另外考虑目标所有权。','struct S {int n;}; struct S x={3}; struct S *p=&x; p->n=8; x.n 为什么改变？','p->n 等价于 (*p).n，定位到 x 里面的 n 成员并写入 8。p 没有成为另一份独立结构体副本。','先辨别变量是结构体对象还是指针，再把箭头写法还原为解引用加成员访问。');

D('c-types','系统位数为什么不能直接决定全部类型大小？',[
 '硬件能一次处理多少位，与语言如何存储 int、long、指针不是同一个约定。编译器还遵循 ABI，让不同函数与库对布局和传参达成一致。',
 '常见 ILP32 的 int、long、指针都是 4 字节；LP64 的 int 仍为 4，long 与指针为 8；LLP64 的 long 仍为 4。这解释了为何同为 64 位，long 可能不同。',
 '做 sizeof 题先写平台模型，再算对象构成。固定宽度接口可用 stdint.h 类型；普通 int 则不要仅凭“32 位或 64 位系统”猜大小。'
],'char 恒占 1 个 C 字节，但是否有符号、一个字节几位是不同问题；uint32_t 的存在需要实现支持精确 32 位类型。','类型大小由语言约束和 ABI 共同决定。64 位不保证 int 为 8 字节。我会先确认 ILP32、LP64 或 LLP64，再分别计算数组、指针和结构体。','LP64 中 int a[4] 与 int *p 分别占多少？','常见 LP64 的 int 为 4 字节、指针为 8 字节，因此完整数组 a 为 16 字节，p 为 8 字节。','先列出各类型的大小，再计算元素数和对齐；不要让一个平台数字代替所有类型。');
D('c-conversion','为什么看似简单的比较，必须先判断类型？',[
 '运算之前可能先发生整数提升和通常算术转换。小整数类型往往先提升成 int，二元操作再选择能共同运算的类型，所以源变量类型不总是最终计算类型。',
 '在常见 32 位 int 与 unsigned int 同等级环境，混合运算常将有符号值转为 unsigned int。负数转换后得到对应模 2^32 的非负值，比较语义随之改变。',
 '强制转换也要看发生时机。两个 int 先相除再转 double，小数已经丢失；先把一个操作数转 double，才会进行浮点除法。'
],'无符号回绕是规定的模运算；有符号溢出在这些 C 示例中是未定义行为。不要把两者混同。','我先判断提升和共同类型，再计算数值。有符号与无符号混合可能使负数变成很大的无符号值；整数除法要在运算前转换才可保留小数。','int a=3,b=2; double x=(double)(a/b),y=(double)a/b; x 与 y 相同吗？','不同。a/b 先做整数除法得到 1，x 为 1.0；y 的除法有 double 操作数，得到 1.5。','给每个子表达式标注类型，把转换发生在运算前还是运算后写清。');
D('c-pointer','指针步长与生命周期，为什么要一起检查？',[
 '地址只是目标位置；所指类型决定访问单位。int* 加一前进一个 int，int(*)[4] 加一前进一整行，因此同样的 +1 可以移动不同字节数。',
 '语言只允许规定范围内的指针算术，例如同一数组及其尾后一位。先确认属于哪个数组，再谈下标偏移；指针差也以元素数为单位。',
 '目标退出作用域或被释放后，原地址数值可能还存在，但那个对象已不再有效。安全访问同时依赖类型、范围和生命周期，不能只看 p!=NULL。'
],'非空指针也可能悬空。把地址保存更久，不会延长所指对象的生命周期。','指针访问要检查目标有效、类型合适和范围合法。指针加一按所指类型跨一个对象，尾后指针可作边界但不可解引用；非空不代表安全。','int a[2]; int *p=a+2; 能比较 p 与 a+2 吗？能读取 *p 吗？','可形成并比较同一数组的尾后指针；不可读取 *p，因为那里没有这个数组的有效元素。','先画数组边界，标所指类型，再检查目标是否仍存活。');
D('c-array','为什么函数形参写了数组长度，仍会丢失完整数组类型？',[
 '调用处 int a[5] 是完整数组，sizeof a 对整个对象求大小。在多数普通表达式里，a 会转换成首元素指针，这种转换没有复制数组数据。',
 '函数形参 int a[5] 调整为 int *a。这里的形参对象保存地址，不携带数组实际长度；括号写成 [100] 也不能自动获得 100 个有效元素。',
 '安全接口传地址与有效长度两项。字符串还要单独分清容量和终止零前的长度，strlen 依赖有效的零终止序列，不能拿它测任意二进制缓冲区。'
],'数组不是可以任意重新赋地址的指针变量。sizeof 完整数组和 sizeof 数组形参的结果不能交换使用。','完整数组有元素数量，常见表达式中转为首元素指针；数组形参则调整为指针。函数通常要另传长度，sizeof 指针无法恢复它所指数组的容量。','void f(int a[9]) 内 sizeof a 一定等于 9*sizeof(int) 吗？','不一定，也通常不是。这里 a 是调整后的指针形参，sizeof a 求指针大小；应另传真实有效长度。','先判断当前名字代表完整数组还是调整后的指针，再区分容量与有效数据长度。');
D('c-array-pointer','括号怎样决定“多个地址”还是“一行的地址”？',[
 'int *a[4] 中 a 先与 [] 结合，是包含 4 个元素的数组，每个元素是 int*。可以把它画成四个分别保存地址的格子。',
 'int (*p)[4] 用括号让 p 先与 * 结合，它是一个指针，目标类型是包含 4 个 int 的数组。p 加一就跨过整行的四个整数。',
 '二维 int grid[3][4] 在常见表达式中转为指向第一行的指针，匹配 int (*)[4]。它不等于 int**：后者首先访问的是指针对象，而二维数组行里保存的是整数。'
],'地址打印相同不证明类型相同。把 int[3][4] 强转 int** 不能生成缺失的行指针对象。','指针数组是多个指针组成的数组，数组指针是指向整段数组的一个指针。括号改变结合关系，也改变 +1 步长；二维连续数组不能直接当 int** 使用。','int a[2][3]; int (*p)[3]=a; int 为 4 字节时，p+1 跨多少字节？','跨一个 int[3] 行，共 3×4=12 字节；不是 4 字节，也不是两个行的 24 字节。','从变量名开始，先按括号和 [] 读类型，再算一个目标对象的大小。');
D('c-string','为什么字符串必须在容量之外再讨论结束位置？',[
 'C 字符串以第一个零字符作为结束标志。char s[]="abc" 保存 a、b、c 和末尾零，因此 sizeof s 为 4，而 strlen(s) 为 3。',
 '数组容量限制能写多少元素；当前字符串长度限制逻辑内容到哪里。复制文本还要为末尾零留空间，否则打印或 strlen 可能继续读出缓冲区。',
 '边界处理先确认目标容量，再限制复制长度，最后明确终止。对于带零字节的二进制报文，应传显式字节数，而非用字符串函数推测数据长度。'
],'strncpy 在源长度达到限制时不保证零终止。snprintf 的返回值还需判断截断，不能仅看缓冲区最后呈现的文字。','字符串是零终止字符序列，容量、长度与终止符分别处理。我会给目标留终止零空间，检查截断；二进制消息用显式长度，避免字符串函数越界读取。','char s[3]={\'a\',\'b\',\'c\'}; 为什么不能直接用 strlen(s)？','这个数组没有保证存在有效终止零。strlen 会寻找零，可能读过对象边界；三个字符并不自动组成合法 C 字符串。','分别列出源有效长度、目标容量与终止零位置，逐次检查读写边界。');
D('c-struct','结构体为什么不是成员大小的简单相加？',[
 '成员可能有对齐要求。例如本例 int 要放在偏移为 4 的倍数的位置，前面的 char 用完 1 字节后，需要留空再放 int。空位称为填充。',
 '结构体整体还需适合放入数组。每个元素的起点都要满足成员对齐，所以末尾可能继续填充，使 sizeof 形成合适的元素步长。',
 '计算时从偏移 0 开始，逐成员向上对齐再加成员大小，最后按整体对齐收尾。改变成员顺序可能减少填充，但协议布局不应依赖编译器猜测。'
],'对齐值与 packing 受 ABI、工具链和选项影响。压紧布局还可能造成未对齐访问，不能只为省字节而忽略访问要求。','结构体大小包含成员和填充。先按每个成员的对齐安排偏移，再将整体大小向整体对齐取整。跨设备报文我会按字段编码，避免直接发送原始结构体。','char、int、char 三个成员，大小 1/4/1、对齐 1/4/1 时，为什么常得 12 字节？','偏移为 0、4、8；最后一个 char 结束于偏移 9，整体需按 4 对齐，因此总大小向上补到 12。','逐项填写成员起点和终点，最后再做结构体整体对齐。');
D('c-keywords','四个关键词为什么不能只背一句口号？',[
 'const 限制通过相应访问路径修改，static 的含义随位置变化：局部静态对象延长存储期，文件级 static 常限制链接可见性。先看声明位置再解释。',
 'extern 常用于声明其他位置定义的对象或函数，让编译单元知道名字与类型；它不等于“所有位置都直接分配一份”。声明与定义要分开。',
 'volatile 告诉实现，这些访问不能像普通稳定数据那样随意省略，常见于硬件寄存器。它不同时提供原子读改写、任务互斥和 CPU 内存屏障。'
],'volatile counter++ 仍可能丢失并发更新。是否单次访问原子，以及需要哪些屏障，要结合平台与并发机制。','我按位置解释 static，按访问路径解释 const，按声明和定义解释 extern。volatile 用于特殊可观察访问，但共享数据同步还需锁、原子操作或合适的临界区。','两个任务对 volatile int count 执行 ++，为什么仍可能丢计数？','++ 通常包含读取、加一、写回。两任务都读到旧值 0 再都写 1，只增加了一次；volatile 不把三步合成不可分割操作。','先确认关键词修饰的对象与声明位置，再分开检查可见性、生命周期和同步。');
D('c-bits','置位、清位和翻转为什么分别用不同运算？',[
 '掩码是把需要操作的位置写成 1 的位模式。1u<<k 表示第 k 位，其他位置为 0，位编号从最低位 0 开始。',
 'OR 与 1 运算必为 1，适合置位；AND 与 0 运算必为 0，所以清位要先对掩码取反；XOR 与 1 会切换原位，适合翻转而不保证清零。',
 '读改写寄存器还要看硬件语义。有些标志位写 1 清除，有些寄存器有专用置位/复位入口；普通变量的掩码操作不能直接照搬给全部寄存器。'
],'移位数量需小于操作数有效位宽，宜使用无符号类型。并发修改不同位时，普通读改写也可能互相覆盖。','先构造无符号掩码，再依据真值规则选择置位 OR、清位 AND 取反、翻转 XOR。操作外设时还需查寄存器写入语义，避免误清标志或丢失并发更新。','对一个 uint32_t 变量，为什么 flag ^= 4u 不能保证 bit2 清零？','XOR 会翻转该位：原来为 1 才变 0，原来为 0 则变 1。清零应按该类型使用 flag &= ~4u。','画出掩码与取反掩码，只推演目标位和一个非目标位的真值。');
D('c-heap','分配成功为什么不等于后续使用一直安全？',[
 'malloc 请求一块动态存储，返回空指针表示失败。成功只说明获得了那块区域，还要核对大小计算、防止乘法溢出，并建立数据初始化和所有权。',
 'free 结束这块动态对象的可用期，不会替你清除所有保存该地址的副本。其他别名仍可能悬空，因此“只把一个指针置 NULL”不能修复全部别名。',
 '嵌入式中要考虑最长执行时间、内存峰值和碎片。固定缓冲池能简化容量与生命周期，但取块失败、重复归还和跨任务转移仍需清楚规则。'
],'不要释放非分配器返回的指针或重复释放同一对象。错误路径也要遵循同一个释放责任。','动态内存需要检查分配失败、大小、初始化和所有权。释放后全部别名都不能继续使用；在 MCU 中还会评估碎片、峰值与分配时间，必要时用固定池。','char *p=malloc(8); char *q=p; free(p); p=NULL; q 能继续读取吗？','不能。q 仍保存已释放对象的地址，p 置空只修改 p 这个变量，没有恢复目标生命周期，也没有更新 q。','画出谁申请、谁持有别名、谁负责释放，并跟踪所有失败分支。');
D('c-function','作用域与生命周期，为什么必须分别说明？',[
 '作用域回答代码中哪些位置可用这个名字；生命周期回答对应对象什么时候存在。二者有关联但不相同，例如局部 static 的名字只在块内可见，对象却长期存在。',
 '普通局部自动对象通常随本次函数调用进入和退出而存在。返回它的地址，返回后名字不可用且对象已结束，调用者不能把残留地址当有效结果。',
 '递归每次调用都有独立参数和局部状态，直到遇到终止条件再返回。写函数接口时明确输入长度、输出位置、错误返回和所有权，比只记声明语法更重要。'
],'不要用“地址还没被覆盖”证明局部对象仍存活。递归有正确终止条件也可能因深度过大耗尽栈。','作用域控制名字可见范围，生命周期控制对象存在时间。函数输出可以返回值或写调用者的缓冲区；不能返回普通局部对象的地址。递归还需限定终止条件和深度。','函数里 static int x 与 int y，在返回后的生命周期有什么差别？','局部 static x 具有静态存储期，不随一次调用结束而消失；自动对象 y 的生命周期随所在调用结束。名字可见范围都可局限在函数内。','将名字可见范围和对象存在时间画成两条线，再检查返回数据依赖哪一条。');
D('c-funcptr','回调为什么既需要函数地址，也需要一致的签名？',[
 '函数指针保存可调用函数的地址。int (*f)(int) 的括号先说明 f 是指针，再说明目标是接受 int、返回 int 的函数。',
 '调用者会按这个签名准备参数并解释返回值。如果实际函数类型不匹配，强转地址不能保证传参与返回规则正确。',
 '回调把“什么时候调用”交给框架，把“具体做什么”交给注册者。若另传上下文指针，还要保证上下文在回调使用期间存活，并规定任务或 ISR 上下文。'
],'函数指针与返回指针的函数是不同声明。回调中能否等待，取决于调用它的上下文。','函数指针让程序把行为作为参数传递，签名必须匹配。设计回调时同时说明调用时机、执行上下文、用户数据生命周期和是否允许阻塞。','int *f(int); 与 int (*f)(int); 为什么不是同一种东西？','前者 f 是函数，返回 int*；后者 f 是指针，指向返回 int 的函数。括号改变了名字先与函数参数列表还是星号结合。','先从名字向外读声明，分别列参数类型、返回类型和调用上下文。');
D('c-macro','宏为什么不能按普通函数的调用规则理解？',[
 '函数式宏先做预处理替换，再交给编译器分析表达式。SQR(x) 若写成 x*x，传入 a+b 后会得到 a+b*a+b，而不是自动成为括号里的平方。',
 '给每个参数及整个结果加括号可修复分组问题，但不能保证参数只求值一次。宏中多次出现 x，传入带修改的表达式仍可能多次修改甚至产生未定义行为。',
 '头文件提供声明与共享类型，保护宏避免重复包含同一声明。处理宏题先完整写出替换文本，再按 C 规则推导；工程中优先考虑类型明确的函数或 inline。'
],'不要把 printf 的某个实测输出当作含未定义行为表达式的正确答案。宏里的安全括号不消除全部副作用问题。','宏是预处理替换，先展开再判断优先级。参数与结果都要加括号，仍要防止重复求值；有类型和副作用要求时优先使用函数或 inline。','为什么 #define TWICE(x) ((x)+(x)) 不适合接收 i++？','它把 i++ 替换两次，无法提供普通一次传参求值的保证；在该表达式中对同一对象的无序修改还会产生未定义行为。','先展开完整文本，标出参数出现次数，再检查括号和副作用顺序。');
D('c-union','union 为什么不能同时独立保存全部成员的值？',[
 '结构体成员占各自区域，union 成员共享同一存储区域。写入一个成员会改变其他成员所覆盖的位，因此它适合表达互斥的数据形式。',
 '读取非当前存入的成员，不能自动理解成数值类型转换。C 与 C++ 的规则和例外不同，表示可能无效；跨平台编码宜显式复制字节并按协议解释。',
 'enum 为一组离散状态命名，位域压缩成员的位数，但位域顺序、存储单元和对齐有实现因素。通信协议应显式移位与掩码，避免依赖编译器位域布局。'
],'union 的大小还受最大成员对齐影响。枚举和位域都不能在未知 ABI 下直接当稳定报文格式。','union 表示多个成员共享存储，struct 则各自存储。枚举表达离散状态，位域表达位级字段；跨平台协议布局我会显式编码，不依赖编译器排列。','union U {int i; char c;}; 写 c 后，能说 i 保持先前的独立数值吗？','不能。成员共享覆盖的字节，写 c 已改变那部分存储；其余字节与读取规则也要结合先前写入和实现，不能当两个独立变量。','先画成员是否共享存储，再区分数值转换、位模式解释和协议编码。');
D('c-pointerconst','const 放在星号两侧，为什么限制的是不同对象？',[
 'const int *p 让目标整数通过 p 的访问路径只读；指针对象 p 没有限定为 const，所以还能换一个目标。',
 'int *const p 把 p 自己限定为只读地址，因此不能重新赋指向；目标整数并没有因此变成只读，合法时仍可通过 *p 写入。',
 '两个限制也可以组合为 const int *const p。判断代码是否允许时，只需先确定左边是 p 还是 *p，再看该层有没有只读限制。'
],'底层对象若本来定义为 const，去掉限定后尝试写入仍不合法。只读访问路径不一定意味着对象本身从未变化。','const int* 限制通过指针写目标，int* const 限制指针换地址。我会分开判断指针对象与目标对象，并避免去掉真正只读对象的限定后写入。','int x=1,y=2; const int *p=&x; p=&y; 合法吗？*p=3 呢？','换地址合法，p 自己没有 const 限制；通过 *p 写目标不允许，因为这条访问路径把 int 视为只读。','把“地址变量”和“所指对象”画成两层，将 const 放回它限制的那层。');
D('c-doubleptr','为什么要修改调用者的指针，就要再多传一层地址？',[
 '若调用者有 int *p，普通 int* 参数只复制 p 中保存的地址。函数重新给自己的形参赋值，不会改调用者 p。',
 '传 &p 时，函数收到的是 p 这个指针对象的地址，类型为 int**。写 *pp 相当于写调用者 p；再写 **pp 才访问最终整数。',
 '二级指针常用于更新链表头或返回分配结果。接口还需要说明失败时输出是否变化、谁释放新对象，以及 pp 本身和最终目标的有效性。'
],'并非所有 int** 都表示二维数组。间接层数描述访问关系，不自动决定目标是否连续分配。','二级指针保存指针对象的地址。*pp 可以修改调用者的指针，**pp 访问最终对象；使用它时还要说明输出和资源所有权，不能把它直接等同二维数组。','void set(int **pp,int *q){*pp=q;} 调用 set(&p,&x) 后，为什么 p 会指向 x？','pp 保存 p 的地址，*pp 指定的对象正是调用者 p，所以把 q 中的 x 地址写进了 p。','逐层写出 pp 指向谁、*pp 是什么对象、**pp 最后访问谁。');
D('c-memcpy','重叠拷贝为什么需要 memmove 的额外保证？',[
 'memcpy 复制指定数量的字节，要求有效源与目标范围且不重叠。它不寻找字符串结束符，也不会替你判断目标容量。',
 '重叠时，前面写入的数据可能覆盖后面尚未读取的源数据。memmove 保证结果等效于先暂存源字节再写目标，具体实现可用合适的复制方向。',
 '判断题先把两段半开区间画出来，再比较是否相交。还要核对字节数，sizeof 指针不是目标缓冲区容量。'
],'“这次 libc 的 memcpy 刚好反向复制”不能当合法依据。memmove 也不会修复源目标范围越界。','memcpy 要求范围不重叠，memmove 保证重叠时仍得到正确复制结果。两者都按字节数工作，调用者负责容量、有效范围和对象使用条件。','把 a[0..3] 移到 a[1..4]，为什么不能直接认为 memcpy 安全？','源目标区间交叠，写 a[1] 等位置可能覆盖后续源。这里应使用保证重叠语义的 memmove，并确认数组至少覆盖目标区间。','画出源与目标的起点和字节区间，先判重叠，再判容量。');
D('c-ub','为什么有些代码根本不该回答一个确定输出？',[
 '未定义行为表示标准不对该执行施加要求，例如越界访问或此处 C 示例中的有符号溢出。它不等于“必定崩溃”，也不等于“编译器会任选正常答案”。',
 '未指定行为存在标准允许的多种选择，实现不必逐一声明，例如某些操作数求值顺序；实现定义行为则需要实现给出选择的文档。',
 '分析输出题先判断程序是否满足合法前提。若已经出现未定义行为，再计算一个实测输出会掩盖问题；工程中用警告、静态检查和合适的运行检测补证据。'
],'C 与 C++ 不同标准版本的部分规则不同，解释应标清语言和版本。不能把所有“不确定”都叫未定义行为。','输出题先检查合法性。未定义行为没有标准保证，未指定有若干合法选择，实现定义需要实现文档说明。定位时我会先修复越界、生命周期或溢出前提。','越界代码在两台电脑都打印 0，能据此认为标准答案为 0 吗？','不能。重复出现的现象只说明那些运行条件下观测到了 0，不能为已经越界的代码建立语言保证。','先按对象范围、生命周期、运算范围和修改顺序检查，再考虑输出。');
D('c-float','为什么十进制 0.1 在二进制浮点里经常只能近似？',[
 '二进制浮点用有限位保存有效数字与指数，类似科学计数法。只有能在有限二进制位内展开的数才能精确表示；0.1 的二进制展开是无限循环。',
 '每次运算都可能舍入到可表示值，误差会受量级和操作影响。大数附近相邻浮点数间距更大，加一个很小的量可能得不到变化。',
 '比较误差时需结合业务容差与量级，常综合绝对误差和相对误差；金额或精确计数可考虑整数单位与明确的缩放规则。'
],'不是所有浮点比较都必须禁止 ==，精确可表示值和离散状态有不同需求。NaN 的比较规则也需要单独考虑。','浮点是有限精度的二进制表示，许多十进制小数需要舍入。比较时结合业务误差和量级，不机械使用固定容差；精确计数可以选合适的整数表示。','为什么 double 通常比 float 精度更高，却仍不保证精确保存 0.1？','double 通常提供更多有效二进制位，近似误差更小，但有限位数仍无法容纳 0.1 的无限二进制展开。','先区分表示误差、运算舍入和量级，再说明业务允许的误差尺度。');
